insert into public.books (id, class_id, subject_id, language, title, supplied)
insert into public.guide_questions (id, book_id, guide_source, question_text, question_type, options, answer_key, guide_solution, marks, set_id, section, stimulus_text, chapter_number, out_of_syllabus)
values
  ('ict-lec-ch01-mcq-445', 'class9-ict-bn-guide', 'ict-lecture-satt', 'তথ্য প্রযুক্তির উন্নয়নের ফলে বিনোদন জগতে যে নতুন বিনোদনের জন্ম হয়েছে', 'mcq', '{"ক":"সঙ্গীতকে আধুনিক রূপ দেওয়া সম্ভব হওয়ায় মিউজিক","খ":"মুভি (প্রয়োগ) ওয়াডর্ প্রসেসর কম্পিউটার গেম","গ":"ইন্টারনেট ওয়াল্ডর্ ওয়াইড ডিজিটাল ভাসর্ন তৈরি করা যায় ঘ","ঘ":"অনুষ্ঠানমালা রেকডর্ করে রাখা যায়"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 1, false),
  ('ict-lec-ch01-mcq-506', 'class9-ict-bn-guide', 'ict-lecture-satt', 'কোন আবিষ্কারকের আবিষ্কারের ফলে চিকিৎসকের সাথে যোগাযোগ করে। আজকের পৃথিবীতে ঘরে বসেই তিনি সুমনকে দ্রম্নত হাসপাতালে যেতে অফিসের কাজ করা সম্ভব হচ্ছে? বলেন। পরে হাসপাতালের ডাক্তার ঢাকার', 'mcq', '{"ক":"চালর্স ব্যাবেজ বিশেষজ্ঞ ডাক্তারের পরামশর্ গ্রহণ করে","খ":"অ্যাডা লাভলেস সুমনের চিকিৎসার ব্যবস্থা করলেন।","গ":"জেমস ক্লাকর্ ম্যাক্সওয়েল","ঘ":"জগদীশ চন্দ্র বসু ডাক্তারের পরামশর্ গ্রহণ করতে পারেন"}'::jsonb, 'ক', null, 1, null, 'mcq_bank', null, 1, false),
  ('ict-lec-ch01-saq-001', 'class9-ict-bn-guide', 'ict-lecture-satt', 'কুড়িগ্রামের রৌমারি উপজেলার জাদুর চর গ্রামের মিলন বাড়িতে বসেই উচ্চশিক্ষা গ্রহণ করতে চায়। তথ্য ও যোগাযোগ প্রযুক্তি কীভাবে তাকে সাহায্য করতে পারে?', 'short', null, null, 'কুড়িগ্রামের রৌমারি উপজেলার যাদুর চর গ্রামের মিলন এখন নিজ গ্রামেই বসে উচ্চশিক্ষা গ্রহণ করতে পারবে, যা সম্ভব হবে ই-লানির্ং পদ্ধতির মাধ্যমে। ই-লানির্ং হলো ইলেকট্রনিক লানির্ং এর সংক্ষিপ্ত রূপ, যা ডিজিটাল প্রযুক্তির সাহায্যে শিক্ষালাভের একটি আধুনিক পদ্ধতি। বতর্মানে বিভিন্ন বিশ্ববিদ্যালয় ও শিক্ষাপ্রতিষ্ঠান তাদের কোসর্ অনলাইনে উন্মুক্ত করে দিয়েছে, ফলে শিক্ষাথীর্রা যে কোনো স্থান থেকে এই কোসর্ করতে পারে। মিলনও চাইলে এসব কোসের্ ভতির্ হয়ে ভিডিও লেকচার দেখতে, লাইভ ক্লাসে অংশ নিতে, হোমওয়াকর্ জমা দিতে এবং অনলাইন পরীক্ষায় অংশগ্রহণ করে ক্রেডিট অজর্ন করতে পারবে। তবে ই-লানির্ং ব্যবহারের জন্য মিলনের কাছে কম্পিউটার, উচ্চগতির ইন্টারনেট সংযোগ, আইএসপি ও প্রয়োজনীয় সফটওয়্যার থাকতে হবে। এই প্রযুক্তি ব্যবহার করে মিলন ঘরে বসেই উচ্চশিক্ষা চালিয়ে যেতে পারবে এবং নিজের স্বপ্ন পূরণের পথে এগিয়ে যেতে সক্ষম হবে। তথ্যপ্রযুক্তির উন্নতির ফলে গ্রামাঞ্চলেও উচ্চশিক্ষা এখন সহজলভ্য হয়ে উঠেছে।', null, null, 'short', null, 1, false),
  ('ict-lec-ch01-saq-003', 'class9-ict-bn-guide', 'ict-lecture-satt', 'একুশ শতকের সম্পদের ধারণাটি ব্যাখ্যা কর।', 'short', null, null, 'বিগত শতাব্দীতে সম্পদের যে ধারণা ছিল, একুশ শতকে এসে সেটি পুরোপুরি পাল্টে গেছে। পৃথিবীর সবাই মেনে নিয়েছে যে, একুশ শতকের সম্পদ হচ্ছে জ্ঞান। যার অথর্ কৃষি, খনিজ সম্পদ কিংবা শক্তির উৎস নয়, শিল্প কিংবা বাণিজ্যও নয়। এখন পৃথিবীর সম্পদ হচ্ছে সাধারণ মানুষ। তার কারণ শুধু মানুষই জ্ঞান সৃষ্টি করতে পারে, জ্ঞান ধারণা করতে পারে এবং জ্ঞান ব্যবহার করতে পারে। পৃথিবীর সম্পদের এই নতুন ধারণাটি সারা পৃথিবীতেই মানুষের চিন্ত্মাভাবনার জগৎটি পাল্টে দিয়েছে। পৃথিবীর মানুষ এখন একুশ শতকের মুখোমুখি হওয়ার জন্য আলাদাভাবে প্রস্তুতি নিতে শুরম্ন করেছে। তারা অনুভব করতে পেরেছে একুশ শতকের পৃথিবীটা আসলে জ্ঞানভিত্তিক একটা অর্থনীতির উপর দাঁড়াতে শুরম্ন করেছে। তাই এখন যারা জ্ঞানভিত্তিক সমাজ তৈরির বিপস্নবে অংশ নিবে তারাই একদিন পৃথিবীর চালিকাশক্তি হিসেবে কাজ করবে।', null, null, 'short', null, 1, false),
  ('ict-lec-ch01-saq-005', 'class9-ict-bn-guide', 'ict-lecture-satt', 'তথ্য ও যোগাযোগ প্রযুক্তির বিকাশে অ্যাডা লাভলেসের ভূমিকা ব্যাখ্যা কর।', 'short', null, null, 'আধুনিক কম্পিউটারের জনক চালর্স ব্যাবেজ ডিফারেন্‌স ইঞ্জিন ও এনালিটিক্যাল ইঞ্জিন নামে দুইটি গণনা যন্ত্র তৈরি করেন। এই ইঞ্জিনগুলো যান্ত্রিকভাবে গণনার কাজ করতে পারত। তবে গণনার কাজটি কীভাবে আরও কাযর্কর করা যায় তা নিয়ে কাজ করেছিলেন অ্যাডা লাভলেস। তিনি লডর্ বায়রনের কন্যা। মায়ের কারণে তিনি ছোটবেলা থেকে বিজ্ঞান ও গণিতে আগ্রহী ছিলেন। ১৮৩৩ সালে চালর্স ব্যাবেজের সাথে তার পরিচয় হলে তিনি এনালিটিক্যাল ইঞ্জিনকে কাজে লাগানোর জন্য প্রোগ্রামিং এর ধারণা সামনে নিয়ে আসেন। এ কারণে তাকে প্রোগ্রামিং ধারণার প্রবতর্ক হিসেবে সম্মানিত করা হয়। ১৮৪২ সালে চালর্স ব্যাবেজ তুরিন বিশ্ববিদ্যালয়ে তার ইঞ্জিন সম্পকের্ বক্তৃতা দেন। সে সময় অ্যাডা লাভলেস ব্যাবেজের সহায়তা নিয়ে পুরো বক্তব্যের সঙ্গে ইঞ্জিনের কাজের ধারণাটি বণর্না করেন। কাজের ধারা বণর্না করার সময় তিনি এটিকে ধাপ অনুসারে ক্রমাঙ্কিত করেন। অ্যাডা লাভলেসের মৃত্যুর ১০০ বছর পর ১৯৫৩ সালে সেই নোট আবার প্রকাশিত হলে বিজ্ঞানীরা বুঝতে পারেন, অ্যাডা লাভলেস তুরিন বিশ্ববিদ্যালয়ে আসলে অ্যালগরিদম প্রোগ্রামিংয়ের ধারণাটাই প্রকাশ করেছিলেন।', null, null, 'short', null, 1, false),
  ('ict-lec-ch01-saq-006', 'class9-ict-bn-guide', 'ict-lecture-satt', 'তথ্য ও যোগাযোগ প্রযুক্তির বিকাশে রেমন্ড স্যামুয়েল টমলিনসন ও স্টিভ জবসের ভূমিকা ব্যাখ্যা কর।', 'short', null, null, 'রেমন্ড স্যামুয়েল টমলিনসন: বিশ শতকে ইলেকট্রনিক্সের বিকাশের পর প্রথমে আইবিএম কোম্পানি মেইনফ্রেম কম্পিউটার তৈরি করে পযার্য়ক্রমে ১৯৭১ সালে মাইক্রোপ্রসেসর আবিষ্কৃত হলে সাশ্রয়ী কম্পিউটার তৈরির পথ সুগম হয়। বিশ শতকের ষাট সত্তরের দশকে ইন্টারনেট প্রটোকল ব্যবহার করে আরপানেটের জন্ম হয়। তখন থেকে নেটওয়াকের্র মাধ্যমে কম্পিউটারসমূহের মধ্যে আন্ত্মঃসংযোগ বিকশিত হতে শুরম্ন করে। আর এই বিকাশের ফলে তৈরি হয় ইন্টারনেট। ১৯৭১ সালে আরপানেটে ইলেকট্রনিক মাধ্যমে পত্রালাপের সূচনা করেন আমেরিকার প্রোগ্রামার রেমন্ড স্যামুয়েল টমলিনসন। তিনিই প্রথম ই-মেইল সিস্টেম চালু করেন। স্টিভ জবস: মাইক্রোপ্রসেসরের আবিভাের্বর পর স্টিভ জবস ও তার দুই বন্ধু স্টিভ জজনিয়াক ও রোনাল্ড ওয়েনে ১৯৭৬ সালের ১ এপ্রিল অ্যাপল কম্পিউটার নামে একটি প্রতিষ্ঠান চালু করেন। প্রতিষ্ঠানটি বতর্মান বিশ্বের অন্যতম বৃহৎ প্রতিষ্ঠান। এই প্রতিষ্ঠানের হাতেই পাসোর্নাল কম্পিউটারের নানা পযার্য় বিকশিত হয়েছে।', null, null, 'short', null, 1, false),
  ('ict-lec-ch02-saq-001', 'class9-ict-bn-guide', 'ict-lecture-satt', 'তোমার এক বন্ধু প্রায়ই কম্পিউটারে গেমস খেলে। এতে তার কী কী ক্ষতি হতে পারে? বণর্না কর।', 'short', null, null, 'যদি তোমার বন্ধু অতিরিক্ত কম্পিউটারে গেমস খেলে, তবে এটি তার শারীরিক, মানসিক এবং সামাজিক জীবনে নানা ধরনের ক্ষতিকর প্রভাব ফেলতে পারে। শারীরিকভাবে, দীঘর্সময় স্ক্রিনের সামনে বসে থাকার ফলে চোখের সমস্যা, মাথাব্যথা, পিঠ ও ঘাড়ের ব্যথা এবং স্থূলতা দেখা দিতে পারে। নিয়মিত শরীরচচার্ ও খেলাধুলার অভাবে তার শরীর দুবর্ল হয়ে যেতে পারে এবং ক্লান্ত্মি ও অবসাদ বাড়তে পারে। মানসিকভাবে, গেমের প্রতি আসক্তি তৈরি হলে পড়াশোনায় অমনোযোগিতা, মনোসংযোগের অভাব এবং ধৈযর্ কমে যাওয়া দেখা দিতে পারে। সহিংস গেম বেশি খেলার ফলে তার আচরণ আগ্রাসী হয়ে উঠতে পারে এবং বাস্ত্মব জীবনে ধৈযর্শীলতা ও সহমমির্তার অভাব দেখা দিতে পারে। সামাজিকভাবে, যদি সে অতিরিক্ত সময় গেম খেলায় ব্যয় করে, তবে বন্ধু ও পরিবারের সঙ্গে সম্পকর্ দুবর্ল হয়ে যেতে পারে এবং বাস্ত্মব জীবনের কাজকমের্ আগ্রহ হারাতে পারে। অনেক সময় গেমের জন্য অতিরিক্ত ইন্টারনেট বা ডিভাইস ব্যবহারের কারণে খরচ বেড়ে যায়, যা পরিবারের জন্য আথির্ক চাপ তৈরি করতে পারে। এসব সমস্যা এড়াতে তার উচিত গেম খেলার সময় নিদির্ষ্ট করে দেওয়া, শারীরিক ও সামাজিক কাযর্ক্রমে অংশ নেওয়া এবং পড়াশোনায় মনোযোগী হওয়া। ব্যালান্স বজায় রেখে গেম খেলা গেলে ক্ষতির আশঙ্কা কমে যায় এবং সে সুস্থ ও সফল জীবনযাপন করতে পারবে।', null, null, 'short', null, 2, false),
  ('ict-lec-ch02-saq-002', 'class9-ict-bn-guide', 'ict-lecture-satt', '''কম্পিউটারের সাধারণ ট্রাবলশ্যুটিং জেনে রাখা অত্যন্ত্ম গুরম্নত্বপূণর্''—উক্তিটি যুক্তিসহ ব্যাখ্যা কর।', 'short', null, null, '''কম্পিউটারের সাধারণ ট্রাবলশ্যুটিং জেনে রাখা অত্যন্ত্ম গুরম্নত্বপূণর্''—উক্তিটি যথাতর্। বতর্মান যুগে কম্পিউটার আমাদের দৈনন্দিন জীবনের অপরিহাযর্ অংশ হয়ে উঠেছে। পড়াশোনা, অফিসের কাজ, বিনোদন কিংবা যোগাযোগ-সব ক্ষেত্রেই কম্পিউটার ব্যবহৃত হয়। কিন্তু বিভিন্ন সময় কম্পিউটার হঠাৎ করে বন্ধ হয়ে যাওয়া, ধীরগতিতে কাজ করা, ইন্টারনেট সংযোগ সমস্যা বা সফটওয়্যারজনিত ত্রম্নটি দেখা দিতে পারে। এসব সমস্যার সমাধান বা ট্রাবলশ্যুটিং সম্পকের্ পূবের্ ধারণা থাকলে দ্রম্নত সমাধান করা সম্ভব হয় এবং কাজের বিঘ্ন কমে। যদি কেউ সাধারণ ট্রাবলশ্যুটিং না জানে, তবে সামান্য সমস্যার জন্যও বিশেষজ্ঞ বা টেকনিশিয়ানের সাহায্য নিতে হতে পারে, যা অতিরিক্ত সময় ও অথের্র অপচয় ঘটাতে পারে। উদাহরণস্বরূপ, কম্পিউটার ধীরগতির হয়ে গেলে অপ্রয়োজনীয় ফাইল মুছে ফেলা, র্যাম পরিষ্কার করা কিংবা ডিস্ক ডিফ্র ্যাগমেন্ট করা জানতে পারলে সহজেই সমস্যার সমাধান করা সম্ভব। আবার, ইন্টারনেট সংযোগে সমস্যা হলে রাউটার রিস্টাটর্ দেওয়া, ক্যাবল চেক করা বা ব্রাউজারের ক্যাশ ক্লিয়ার করা সাধারণ ট্রাবলশ্যুটিংয়ের অংশ। এছাড়া, যদি কোনো সফটওয়্যার কাজ না করে, তবে সেটি পুনরায় ইনস্টল করা, আপডেট করা বা কম্প্যাটিবিলিটি চেক করা জানা থাকলে দ্রম্নত সমস্যার সমাধান করা যায়। সাধারণ ট্রাবলশ্যুটিং জানার ফলে কাজের দক্ষতা বৃদ্ধি পায়, সময় বাঁচে এবং প্রযুক্তির প্রতি আত্মবিশ্বাস গড়ে ওঠে। তাই, কম্পিউটার ব্যবহারকারীদের জন্য সাধারণ ট্রাবলশ্যুটিং জানা অত্যন্ত্ম গুরম্নত্বপূণর্।', null, null, 'short', null, 2, false),
  ('ict-lec-ch02-saq-015', 'class9-ict-bn-guide', 'ict-lecture-satt', 'সামাজিক যোগাযোগ সাইটে কী ধরনের সতকর্তা মেনে চলা প্রয়োজন? ব্যাখ্যা কর।', 'short', null, null, 'বতর্মানে অনেকে সামাজিক যোগাযোগ সাইটে নিজের ব্যক্তিগত তথ্য রেখে দেন। ব্যক্তিগত ছবিও অনেকে শেয়ার করে থাকে। তাই ফেসবুক অ্যাকাউন্টের পাসওয়াডর্ কেউ জেনে ফেললে তাতে ব্যক্তিগত তথ্যের নিরাপত্তা বিঘ্নিত হতে পারে। এ কারণে সামাজিক যোগাযোগের সাইট ব্যবহারের সময় নিম্নোক্ত সতকর্তা মেনে চলা প্রয়োজন: • কাউকে ''বন্ধু'' বানানোর আগে তার সম্পকের্ নিশ্চিত হওয়া, বাস্ত্মব জীবনে যে বন্ধু হওয়ার যোগ্য নয়, সামাজিক যোগাযোগ সাইটেও তাকে বন্ধু বানানো যাবে না। • ভাচুর্য়াল বা বিদেশে অবস্থানকারীদের বন্ধু বানানোর সময় তার পরিচয় সম্পকের্ সম্যকভাবে নিশ্চিত হওয়া, এজন্য তার প্রোফাইল দেখা, পারস্পরিক বন্ধুদের মধ্যে কেউ পরিচিত কিনা সেসব বিষয় দেখে নিশ্চিত হওয়া প্রয়োজন। • খুবই ব্যক্তিগত ছবি ফেসবুকে প্রকাশ করা থেকে বিরত থাকা। • মোবাইলে ফেসবুক/ই-মেইল ব্যবহার করার পর, প্রতিবারই লগআউট করা। • স্কুল, সাইবার ক্যাফেতে ইন্টারনেট ব্যবহার করার পর সাইন আউট করা। • বন্ধুর বা পরিচিত কারও ল্যাপটপ বা কম্পিউটার ব্যবহারের সময় সতকর্ থাকা। • কোনো অপরিচিত ব্যক্তির কাছ থেকে কোনো ফেসবুক অ্যাপিস্নকেশন ব্যবহারের অনুরোধ এলে, নিশ্চিত না হয়ে তাতে ক্লিক না করা।', null, null, 'short', null, 2, false),
  ('ict-lec-ch02-saq-017', 'class9-ict-bn-guide', 'ict-lecture-satt', 'কম্পিউটার গেমে আসক্তির বিষয়টি ব্যাখ্যা কর।', 'short', null, null, 'কম্পিউটার গেমে আসক্তিটা প্রায় সময়েই শুরম্ন হয় শৈশব থেকে এবং বেশিরভাগ সময়ই সেটা ঘটে অভিভাবকদের অজ্ঞতার কারণে। কম্পিউটার একটা ঞড়ড়ষ এবং এটা দিয়ে নানা ধরনের কাজ করা যেতে পারে। এই প্রযুক্তি সম্পকের্ এত সুন্দর সুন্দর কথা বলা হয়েছে যে অনেক সময়ই অভিভাবকরা ধরে নেন এটা দিয়ে যা কিছু করা হয় সেটাই বুঝি ভালো, তাই যখন তারা দেখেন তাদের সন্ত্মানেরা দীঘর্ সময় কম্পিউটারের সামনে বসে আছে তারা বুঝতে পারেন না তার মাঝে সতকর্ হওয়ার ব্যাপার রয়েছে। কম্পিউটার গেম এক ধরনের বিনোদন এবং এই বিনোদনের নানা রকম মাত্রা রয়েছে। যারা সেটি খেলছে তারা সেটাকে নিছক বিনোদন হিসেবে নিয়ে মাত্রার ভেতরে ব্যবহার করলে সেটি যেকোনো সুস্থ বিনোদনের মতোই হতে পারে। কিন্তু প্রায় সময়ই সেটি ঘটে না। কোরিয়ায় একজন মানুষ টানা পঞ্চাশ ঘণ্টা কম্পিউটার গেম খেলে মৃত্যুর কোলে ঢলে পড়েছিল। কাজেই এ বিষয়ে সবার সতকর্ হওয়া জরম্নরি। এক গবেষণায় দেখা গেছে কোনো একটা কম্পিউটার গেমে তীব্রভাবে আসক্ত একজন মানুষের মস্ত্মিষ্কে বিশেষ উত্তেজক রাসায়নিক দ্রব্যের আবিভার্ব হয়। শুধু তাই নয় যারা সপ্তাহে অন্ত্মত ছয় দিন টানা দশ ঘণ্টা করে কম্পিউটার ব্যবহার করে তাদের মস্ত্মিষ্কের গঠনেও এক ধরনের পরিবতর্ন হয়ে যায়। কাজেই কম্পিউটার গেম চমৎকার একটা বিনোদন হতে পারে- কিন্তু এতে আসক্ত হওয়া খুব সহজ এবং তার পরিণতি মোটেও ভালো নয়, সেটা সবাইকে মনে রাখতে হবে।', null, null, 'short', null, 2, false),
  ('ict-lec-ch03-mcq-060', 'class9-ict-bn-guide', 'ict-lecture-satt', 'কিন্ডল কোন কোম্পানির তৈরি?', 'mcq', '{"ক":"ফেসবুক","খ":"ইয়াহু গ ঘ","গ":"ব্রেইন","ঘ":"নরটন (প্রয়োগ)"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 3, false),
  ('ict-lec-ch03-saq-001', 'class9-ict-bn-guide', 'ict-lecture-satt', 'আইসিটি কীভাবে আমাদের ক্যারিয়ার গঠনে সহায়ক হতে পারে? ব্যাখ্যা কর।', 'short', null, null, 'তথ্য ও যোগাযোগ প্রযুক্তি (ICT) বতর্মান যুগে ক্যারিয়ার গঠনের জন্য অত্যন্ত্ম গুরম্নত্বপূণর্ ভূমিকা পালন করে। এটি শুধু আমাদের দক্ষতা বাড়ায় না, বরং চাকরির সুযোগ সৃষ্টি করে এবং বিভিন্ন পেশায় সফল হতে সাহায্য করে। নিচে বিস্ত্মারিত ব্যাখ্যা করা হলো-', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-003', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ডিজিটাল কনটেন্ট কী? এর প্রকারভেদ আলোচনা কর।', 'short', null, null, 'ডিজিটাল কনটেন্ট: কোনো তথ্য আধেয় বা কনটেন্ট যদি ডিজিটাল উপাত্ত আকারে বিরাজ করে, প্রকাশিত হয় কিংবা প্রেরিত-গৃহীত হয় তাহলে সেটিই ডিজিটাল কনটেন্ট। তবে সেটি ডিজিটাল বা এনালগ যেকোনো পদ্ধতিতেই সংরক্ষিত হতে পারে। ডিজিটাল কনটেন্ট কম্পিউটারের ফাইল আকারে অথবা ডিজিটাল পদ্ধতিতে সম্প্রচারিত হতে পারে। লিখিত তথ্য, ছবি, শব্দ কিংবা ভিডিও সব ধরনের ডিজিটাল কনটেন্ট হতে পারে। ডিজিটাল কনটেন্ট এর প্রকারভেদ: ডিজিটাল কনটেন্টকে প্রধানত চারটি ভাগে ভাগ করা যায়। যথা:', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-008', 'class9-ict-bn-guide', 'ict-lecture-satt', 'শিক্ষাথীের্দর তৈরিকৃত ক্লাবে ইন্টারনেটের ভূমিকা আলোচনা কর।', 'short', null, null, 'শিক্ষাথীর্রা পাঠ্যপুস্ত্মকে যেটুকু থাকে সেটুকুতে সন্তুষ্ট থাকে না। শিক্ষাথীর্রা আরও বেশি জানতে ও শিখতে চায়। সেজন্য সব স্কুল-কলেজের শিক্ষাথীর্রা তাদের শখের বিষয় যেমন: বিজ্ঞান, গণিত, শারীরিক শিক্ষা কিংবা সাহিত্যের ক্লাব তৈরি করে। এই ক্লাবগুলোতে এক সময় শুধু শারীরিকভাবে উপস্থিত ছেলেমেয়েরাই অংশ নিতে পারত। কিন্তু ইন্টারনেট হওয়ার কারণে বিষয়টা এখন পুরোপুরি উন্মুক্ত হয়ে গেছে। এখন সারা দেশের এমনকি সারা পৃথিবীর ছেলেমেয়েরা শারীরিকভাবে উপস্থিত না হয়েও এই ক্লাবগুলোতে অংশ নিতে পারে। ফলে শিক্ষাথীর্রা সবাই মিলে পাঠ্যজগতের বিষয়গুলোকে অন্য একটা পযাের্য় নিয়ে যেতে পারে। এ কারণে শিক্ষাথীের্দর তৈরিকৃত ক্লাবে ইন্টারনেটের ভূমিকা অত্যন্ত্ম গুরম্নত্বপূণর্।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-009', 'class9-ict-bn-guide', 'ict-lecture-satt', 'আমাদের ভবিষ্যৎ ক্যারিয়ার গঠনে আইসিটির ভূমিকা আলোচনা কর।', 'short', null, null, 'ভবিষ্যতে আইসিটিবিহীন একটি দিনও কল্পনা করা সম্ভব নয়। আইসিটির সবর্মুখী ব্যবহারের কারণে কোনো প্রতিষ্ঠানের কমীর্ হিসেবে যোগ দেওয়া কিংবা নিজেই একটা প্রতিষ্ঠান তৈরি উভয় ক্ষেত্রে আইসিটিকে এড়িয়ে যাওয়া সম্ভব হবে না। নিজের ক্যারিয়ারের ক্ষেত্রে তাই আইসিটিতে দক্ষতা উন্নয়নের জন্য নিজেকে যথেষ্ট সচেতন হতে হবে। সাধারণ অফিস সফটওয়্যারের ব্যবহার, ইন্টারনেট, ই-মেইল, সামাজিক যোগাযোগের মাধ্যমসহ প্রায় সব কিছুতেই প্রাথমিক দক্ষতা না থাকলে আগামীতে কোথাও চাকরি পাওয়া কঠিন হবে। অন্যদিকে প্রোগ্রামিং, ওয়েবসাইট বিনিমার্ণ, কম্পিউটার নিরাপত্তা ইত্যাদি বিশেষায়িত কাজের চাহিদাও বিপুল পরিমাণে বৃদ্ধি পাচ্ছে। বিশ্বব্যাপী তথ্য ও যোগাযোগ প্রযুক্তি ক্যারিয়ার গঠনের একটি বড় ক্ষেত্র। তথ্য প্রযুক্তির প্রধান উপকরণটি বলা চলে কম্পিউটার। এ কম্পিউটারে যে কত শত কাজ আছে তা কল্পনাতীত। কম্পিউটার, ইন্টারনেট, মোবাইল, কল সেন্টার ইত্যাদি সবই এর অন্ত্মভুর্ক্ত। কম্পিউটার সায়েন্স, কম্পিউটার ইঞ্জিনিয়ারিং, অফিস অটোমেশন সিস্টেম ডিজাইন, আটিির্ফশিয়াল ইন্টিলিজেন্স, রোবোটিক ইঞ্জিনিয়ারিং, মোবাইল কমিউনিকেশন, ডেটা কমিউনিকেশন এমন হাজারটি ক্যারিয়ারের নাম বলা যায়। সুতরাং আমরা বলতে পারি, আইসিটিতে দক্ষ হলে ভবিষ্যতে দেশে ও বিদেশে ক্যারিয়ার গঠনের অপার সম্ভাবনা রয়েছে।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-010', 'class9-ict-bn-guide', 'ict-lecture-satt', 'দশটি আইসিটিবিষয়ক ক্যারিয়ারের নাম উলেস্নখ কর।', 'short', null, null, 'নিচে দশটি আইসিটিবিষয়ক ক্যারিয়ারের নাম উলেস্নখ করা হলো: • কম্পিউটার সায়েন্স • মোবাইল কমিউনিকেশন • কম্পিউটার ইঞ্জিনিয়ারিং • ডেটা কমিউনিকেশন • অফিস অটোমেশন সিস্টেম ডিজাইনার • বায়োইনফরমেটিক্স • আটিির্ফশিয়াল ইন্টিলিজেন্স • কমিউনিকেশন ইঞ্জিনিয়ারিং • রোবোটিক ইঞ্জিনিয়ারিং • সফটওয়্যার ইঞ্জিনিয়ারিং উলিস্নখিত ক্যারিয়ার ছাড়াও কম্পিউটার তথা আইসিটিবিষয়ক হাজারো ক্যারিয়ার আছে যার ভবিষ্যৎ উজ্জ্বল।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-011', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রোগ্রাম কী? কম্পিউটার প্রোগ্রামিংয়ের গুরম্নত্ব লেখ।', 'short', null, null, 'কম্পিউটারের মাইক্রোপ্রসেসরের জন্য তৈরিকৃত নিদেের্শর সমষ্টিকে প্রোগ্রাম বলা হয়। কম্পিউটারের প্রাণশক্তি বলতে গেলে এ সফটওয়্যারকে বোঝানো হয়ে থাকে, যা কতকগুলো প্রোগ্রামের সমষ্টি। কম্পিউটার প্রোগ্রামিংয়ের গুরম্নত্ব: বিশ্বের বিভিন্ন দেশের মতো বাংলাদেশেও প্রোগ্রামিংয়ে সম্ভাবনার দ্বার দিন দিন উন্মোচিত হচ্ছে। প্রোগ্রামিংয়ের চাহিদা বতর্মানে অনেক বেশি। সবকিছুই এখন কম্পিউটারাইজড হচ্ছে, বিভিন্ন সফটওয়্যার দিয়েই এ প্রোগ্রাম তৈরি করা হয়। স্মাটের্ফানের বিভিন্ন অ্যাপস প্রোগ্রামিংয়ের মাধ্যমেই করা। প্রযুক্তি যেভাবে এগিয়ে যাচ্ছে তাতে একসময় অফিসে বসেই ঘরের টিভি, রেফ্রিজারেটর, এয়ারকন্ডিশন ইত্যাদি নিয়ন্ত্রণ করা যাবে। মোবাইল ডিভাইসের মাধ্যমে মানুষের রোগ নিণর্য় করা যাবে। দিন দিন ইলেকট্রনিক ডিভাইসের আকৃতি ছোট হয়ে আসছে এবং এদের কাযর্ক্ষমতা বৃদ্ধি পাচ্ছে। এটি আরও বৃদ্ধি পাবে। রান্নাঘর থেকে স্যাটেলাইট পরিচালনা পযর্ন্ত্ম সবকিছুই মানুষের হাতের নিয়ন্ত্রণের মধ্যে চলে আসবে। এর সবকিছুই পরিচালিত হবে কম্পিউটার প্রোগ্রামিংয়ের মাধ্যমে। আর তখন কম্পিউটার প্রোগ্রামিংয়ের গুরম্নত্ব আরও বৃদ্ধি পাবে।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-012', 'class9-ict-bn-guide', 'ict-lecture-satt', '''''ভবিষ্যতে আইসিটিবিহীন একটি দিনও কল্পনা করা সম্ভব নয়''''—কথাটির যথাথর্তা আলোচনা কর।', 'short', null, null, 'বতর্মানে সারাবিশ্বে আইসিটির সবর্মুখী ব্যবহারের কারণে কোনো প্রতিষ্ঠানের কমীর্ হিসেবে যোগ দেয়া কিংবা নিজেই একটা প্রতিষ্ঠান তৈরি উভয় ক্ষেত্রে আইসিটিকে এড়িয়ে যাওয়া সম্ভব হবে না। কারণ ভবিষ্যতে আইসিটির উপাদান যেমন: কম্পিউটার, ইন্টারনেট, ই-মেইল, অফিস সফটওয়্যার, সামাজিক যোগাযোগের মাধ্যমসহ প্রায় সকল ক্ষেত্রে প্রাথমিক দক্ষতা না থাকলে চাকরি পাওয়া খুব কঠিন হবে। বতর্মানে শিক্ষাব্যবস্থা অনেকটা আইসিটিনিভর্র হয়ে গেছে। কারণ কম্পিউটার ও ইন্টারনেট ব্যবহার করে শিক্ষাথীর্রা তাদের পাঠের গুরম্নত্বপূণর্ অংশ বা পাঠের সাথে সংশ্লিষ্ট বিষয় সম্বন্ধে প্রয়োজনীয় তথ্যাদি, উপাদান ও উপকরণ সংগ্রহ করতে পারে, ইন্টারনেটের মাধ্যমে ছাত্রছাত্রীরা নিজেদের ঘরে বসেই বিশ্বের বিভিন্ন দেশের কলেজ-বিশ্ববিদ্যালয় সংক্রান্ত্ম যাবতীয় তথ্য সংগ্রহ করতে পারে। এছাড়া শিক্ষাথীর্রা অনলাইনে বিভিন্ন দেশের বড় বড় লাইব্রেরিতে প্রবেশ করে সেখানকার মূল্যবান বইপত্র সংগ্রহ ও অধ্যয়ন করতে পারে। আজকাল অনলাইনে ঘরে বসেই বিশ্বের নামিদামি বিভিন্ন বিশ্ববিদ্যালয়ের বিভিন্ন কোসের্ অংশগ্রহণ করার সুযোগ পাচ্ছে। ছাত্রছাত্রীরা শ্রেণি কক্ষে না গিয়ে বাসায় বসে ইন্টারনেটে ভিডিও কনফারেন্সিংয়ের মাধ্যমে ক্লাসে অংশ নিতে পারছে। আইসিটির ব্যবহারের কারণে সারা বিশ্ব হাতের মুঠোয় চলে এসেছে। ব্যবসা-বাণিজ্য, যোগাযোগ, কমর্সংস্থান, চিকিৎসা, গবেষণাসহ প্রায় সকল ক্ষেত্রে আইসিটির ব্যবহার ব্যাপক হারে বৃদ্ধি পাচ্ছে।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-013', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ফ্রিল্যান্সিং সম্পকের্ কী জান লেখ।', 'short', null, null, 'ফ্রিল্যান্সিং হচ্ছে এক ধরনের প্রক্রিয়া যার মাধ্যমে উন্নত দেশগুলোর ভালো ভালো কোম্পানি তাদের নিজেদের দেশের কমীের্দর দুষ্প্রাপ্যতার কারণে আমাদের মতো উন্নয়নশীল দেশের কমীের্দর ইন্টারনেটের মাধ্যমে ঘরে বসেই কাজ করার সুযোগ দেয়। এর মাধ্যমে বিশ্বের ভালো ভালো প্রোগ্রামাররা নিজ দেশে থেকেই গুগল, মাইক্রোসফট, ইনটেল, ফেসবুকের মতো বিশ্ববিখ্যাত কোম্পানিগুলোতে কাজ করতে পারেন। তাছাড়া প্রোগ্রামাররা ইচ্ছে করলে নিজেরাই সফটওয়্যার ফামর্ খুলতে পারেন। ফ্রিল্যান্সিংয়ের সবচেয়ে বড় সুবিধা হলো অফিসে না গিয়ে ঘরে বসেই কাজ করা যায়। বতর্মানে আমাদের দেশের প্রোগ্রামারসহ বহু আইসিটি কমীর্ ঘরে বসেই ইন্টারনেটের মাধ্যমে কাজ করছে আমেরিকা, কানাডা, ব্রিটেনের মতো দেশগুলোর বড় বড় কোম্পানিতে। ফ্রিল্যান্সের কাজ করার জন্য ধৈযের্র প্রয়োজন হয়। এক্ষেত্রে যোগাযোগের জন্য ইংরেজি ভাষায় ভালো দক্ষতা থাকলেই চলে। বাংলাদেশের অনেকেই নিজের মেধাশক্তিকে কাজে লাগিয়ে ফ্রিল্যান্সার হিসেবে কাজ করে বিশ্বের নামকরা প্রতিষ্ঠানগুলোতে নিজের শক্ত অবস্থান তৈরি করে নিচ্ছে। এক্ষেত্রে আর একটা মজার ব্যাপার হচ্ছে ফ্রিল্যান্সিং কাজে যারা দক্ষ তাদের বড় বড় কোম্পানিগুলোতে আবেদন করতে হয় না। বড় কোম্পানিগুলো নিজেরাই এসব দক্ষ লোকদের খুঁজে নেয়। কমের্ক্ষত্রে ফ্রিল্যান্সিং একটি সম্ভাবনাময়ী সেক্টর। তাই বাংলাদেশ সরকার যদি সহায়তা করে তবে আমাদের দেশের প্রোগ্রামাররা অতি সহজে এই সেক্টরটিকে সম্প্রসারণ করতে পারবে।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-014', 'class9-ict-bn-guide', 'ict-lecture-satt', 'বাংলাদেশে আইসিটির ভবিষ্যৎ সম্পকের্ আলোচনা কর।', 'short', null, null, 'বাংলাদেশ হলো একটি উজ্জ্বল সম্ভাবনাময় দেশ। বাংলাদেশ সরকার ২০২১ সালের মধ্যে বাংলাদেশকে ডিজিটাল বাংলাদেশে রূপান্ত্মরের উদ্যোগ নিয়েছে। এ লক্ষ্যে আইসিটিবিষয়ক সেমিনার, প্রশিক্ষণ এমনকি বিভিন্ন বিশ্ববিদ্যালয়ে আইসিটি নিভর্র পড়াশোনা করানো হচ্ছে শিক্ষাথীের্দর। ফ্রিল্যান্সিং মাধ্যমে যে কেউ ব্যক্তিগতভাবে কাজ শিখে তার প্রয়োগ করতে পারছে। যেসব কোম্পানি নিজেরা সাভার্র ব্যবহার করে তাদের কম্পিউটার নেটওয়াকর্ তৈরির ও রক্ষণাবেক্ষণের জন্য দক্ষ লোক খুবই জরম্নরি। তাই চাকরির বাজারে এর অবস্থানও অনেক ভালো। তথ্য ও যোগাযোগ প্রযুক্তির যুগে দিন দিন বেড়েই চলেছে আইসিটির চাহিদা। পরবতীর্ দুই-তিন বছরের মধ্যে এর চাহিদা দ্বিগুণ হবে বলে অনেকেই মনে করছেন। বাংলাদেশেও ইতিমধ্যে বেশ কিছু সফটওয়্যার কোম্পানি তৈরি হয়েছে যারা বাংলাদেশে তৈরি বিভিন্ন সফটওয়্যার, মোবাইল অ্যাপস পৃথিবীর অন্যান্য দেশে রপ্তানি করছে। এটি আমাদের জন্য অবশ্যই গবের্র। বতর্মান তরম্নণ প্রজন্মের অনেক শিক্ষাথীর্ এই পেশার সঙ্গে জড়িত হয়ে পড়ছে। ভবিষ্যতে এই সেক্টরে আরও অনেক দক্ষ কমীর্র প্রয়োজন হবে। কাজেই ক্যারিয়ার হিসেবে আইসিটির সম্ভাবনা অনেক উজ্জ্বল। এসব বিবেচনা করে নিজের আইসিটি দক্ষতা বাড়িয়ে নিতে এখন থেকেই সচেষ্ট হওয়া প্রয়োজন।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-031', 'class9-ict-bn-guide', 'ict-lecture-satt', 'শিক্ষায় ইন্টারনেটের গুরুত্ব আলোচনা কর।', 'short', null, null, 'বতর্মানে আমাদের দেশের শিক্ষাথীের্দর হাতে কম্পিউটার, ল্যাপটপ, ট্যাবলেট কিংবা স্মাটের্ফান ইত্যাদি চলে এসেছে। অনলাইনে শিক্ষাথীের্দর পড়াশোনার উপযোগী কনটেন্টের পরিমাণ বৃদ্ধি পাচ্ছে। তাই কোনো শিক্ষাথীর্ অনলাইনে কোনো কিছু অধ্যয়ন করতে চাইলে অবশ্যই ইন্টারনেট সংযোগ প্রয়োজন। শিক্ষাথীের্দর শিক্ষণীয় অনেক বিষয় ইন্টারনেটে পাওয়া যায়। কোনো শিক্ষাথীর্ পড়ালেখা করতে করতে কোনো একটা বিষয় বুঝতে না পারলে সে যদি ইন্টারনেটে সেটি অনুসন্ধান করে তবে নিশ্চিতভাবে বলা যায় সে তার উত্তরটি কোনো না কোনোভাবে পেয়ে যাবে। কোনো শিক্ষাথীর্ যদি কোনো নিদির্ষ্ট বিষয় শিখতে চায় কিংবা জানতে চায় তাহলে সে ইন্টারনেটে দক্ষ সাচর্ ইঞ্জিন ব্যবহার করে প্রয়োজনীয় তথ্য খুঁজে বের করতে পারবে। গণিত, বিজ্ঞানসহ প্রায় সকল বিষয়ের ইন্টারনেটে গ্রুপ রয়েছে, ফলে তাদের নিকট যেকোনো প্রশ্ন দেওয়া হলে তার উত্তর দিতে পারবে। তাই আমরা বলতে পারি শিক্ষাক্ষেত্রে ইন্টারনেট একটি গুরুত্বপূণর্ অংশ।', null, null, 'short', null, 3, false),
  ('ict-lec-ch03-saq-032', 'class9-ict-bn-guide', 'ict-lecture-satt', 'বাংলাদেশে ইন্টারনেট ব্যবহারের ক্ষেত্রে কী ধরনের প্রতিকূলতার সম্মুখীন হতে হয়? ব্যাখ্যা কর।', 'short', null, null, 'বাংলাদেশ একটি উন্নয়নশীল দেশ। আমাদের দেশ বতর্মানে তথ্য ও প্রযুক্তি খাতে প্রচুর অথর্ বিনিয়োগ করার ফলে এই খাতে আলোর মুখ দেখার অপেক্ষায় আছে। কিন্তু তথ্যপ্রযুক্তি খাতের সবচেয়ে গুরুত্বপূণর্ দিক হলো ইন্টারনেট প্রাপ্যতা। বাংলাদেশ এখনও ইন্টারনেট ব্যবহারে স্বয়ংসম্পূণর্ নয়। আথির্কভাবে সচ্ছল না হওয়ায় অনেকেই এই সুবিধা গ্রহণে বঞ্চিত। ইন্টারনেট ব্যবহার করার উপযোগী কম্পিউটার, ল্যাপটপ, ট্যাবলেট কিংবা স্মাটের্ফান হাতে চলে এলেই আমরা কিন্তু ইন্টারনেট সুবিধা ভোগ করতে পারি না। তারপর প্রয়োজন হয় ইন্টারনেট সংযোগের। দেশের সব জায়গায় সমানভাবে ইন্টারনেট সংযোগ নেই, তাই সবাই সমানভাবে ইন্টারনেটের স্পিড পায় না এবং ইন্টারনেটের স্পিড কম হলে সেটি ব্যবহার করা অনেক সময় অথর্হীন হয়ে যায়। আবার ভালো স্পিডের ইন্টারনেট পেতে হলে যে পরিমাণ টাকা খরচ করতে হয় সেটি আমাদের দেশের সাধারণ মানুষের সামথের্যর বাইরে। কাজেই শিক্ষায় ইন্টারনেট ব্যবহার করতে হলে আমাদেরকে এই ইন্টারনেট সংযোগটি অনেক সাশ্রয়ী খরচে ছাত্রছাত্রীদের হাতে তুলে দিতে হবে। এছাড়া ইন্টারনেট ব্যবহারকারীরা নানাভাবে বিপযর্স্ত্ম হন। অনেক স্থানে ইন্টারনেট ব্যবস্থা থাকলেও ঐ স্থানে ইন্টারনেট কানেকশন নিয়মিতভাবে বহাল থাকে না। ফলে ইন্টারনেট ব্যবহারে নানা অসুবিধার সম্মুখীন হতে হয়। তাই বাংলাদেশ সরকারের উচিত অতি দ্রুত দেশ তথা জাতির উন্নয়নের জন্য ইন্টারনেট ব্যবস্থা আরও জোরদার ও সাশ্রয়ী করা।', null, null, 'short', null, 3, false),
  ('ict-lec-ch04-saq-002', 'class9-ict-bn-guide', 'ict-lecture-satt', 'স্প্রেডশিট বিশেস্নষণের ৫টি সুবিধা লিখ।', 'short', null, null, 'স্প্রেডশিট বিশেস্নষণের ৫টি সুবিধা নিম্নরূপ—', null, null, 'short', null, 4, false),
  ('ict-lec-ch04-saq-003', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ওয়াডর্ প্রসেসর কী? ওয়াডর্ প্রসেসরে কাজ করার সুবিধাগুলো বণর্না কর।', 'short', null, null, 'ওয়াডর্ প্রসেসর শব্দের অথর্ হলো শব্দ প্রক্রিয়াকারী। কম্পিউটারে কোনো ভাষার বণর্মালা ব্যবহার করে শব্দ গঠন এবং শব্দাবলী ইচ্ছামতো সাজিয়ে নেয়ার কাজে যে সফটওয়্যার ব্যবহার করা হয় তাকেই ওয়াডর্ প্রসেসর হিসেবে চিহ্নিত করা হয়। উইন্ডোজভিত্তিক মাইক্রোসফট ওয়াডর্, লিনাক্স ভিত্তিক ওপেন অফিস ইত্যাদি ওয়াডর্ প্রসেসর প্রোগ্রামের উদাহরণ। ওয়াডর্ প্রসেসরের সুবিধাবলি: ওয়াডর্ প্রসেসরে লেখালেখির কাজ করার সময় আমরা অনেক ধরনের সুবিধা ভোগ করতে পারি। নিচে সেই সুবিধাগুলো বণর্না করা হলো:', null, null, 'short', null, 4, false),
  ('ict-lec-ch04-saq-012', 'class9-ict-bn-guide', 'ict-lecture-satt', 'একটি স্ট্যান্ডাডর্ স্প্রেডশিট প্যাকেজের ব্যবহার লেখ।', 'short', null, null, 'একটি স্ট্যান্ডাডর্ স্পেডশিটের ব্যবহারের ক্ষেত্রসমূহ নিচে উলেস্নখ করা হলো: • দৈনন্দিন হিসাব করার কাজে ব্যবহৃত হয়। •  বাজেট প্রণয়নের কাজে ব্যবহৃত হয়। •  ব্যাংকিং সিস্টেম পরিচালনায় ব্যবহৃত হয়। • অফিসে কমর্চারীদের বেতনের হিসাব নিণের্য় ব্যবহৃত হয়। • স্কুল কলেজের শিক্ষাথীের্দর পরীক্ষার ফলাফল নিণের্য় ব্যবহৃত হয়। • ব্যবসায় মজুদের পরিমাণ নিণের্য় ব্যবহৃত হয়। • বাৎসরিক আয়করের হিসাব নিণের্য় ব্যবহৃত হয়। • বাৎসরিক আয় ব্যয়ের হিসাব করার জন্য ব্যবহৃত হয়। • ব্যবস্থাপকদের সিদ্ধান্ত্ম গ্রহণে টুলরূপে ব্যবহৃত হয়। • বৈজ্ঞানিক ক্যালকুলেশন করা যায়। •  গাণিতিক, ত্রিকোণোমিতিক এবং পরিসংখ্যানের কাজ করা যায়। •  চাটর্ ও গ্রাফের সাহায্যে তথ্যকে আকষর্ণীয় করে রিপোটর্ আকারে উপস্থাপন করা যায়। • ম্যাক্রো ব্যবহার করে কোনো কাজ রেকডর্ করে পরবতীের্ত তা বারবার ব্যবহার করা যায়। • কোনো উৎপাদনমুখী প্রতিষ্ঠানের উৎপাদন ব্যবস্থাপনা করা যায়।', null, null, 'short', null, 4, false),
  ('ict-lec-ch04-saq-013', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ফমুর্লা ও ফাংশন কী? ফমুর্লা ও ফাংশন লেখার নিয়ম ব্যাখ্যা কর।', 'short', null, null, 'ওয়াকির্শটে অন্ত্মভুর্ক্ত বিভিন্ন সংখ্যাগুলোর ভিত্তিতে যোগ, বিয়োগ, গুণ, ভাগ, শতকরা ইত্যাদির হিসাব এর জন্য ব্যবহৃত পদ্ধতিকে বলা হয় ফমুর্লা। ফমুর্লা ব্যবহারের মাধ্যমে বিভিন্ন জটিল হিসাব-নিকাশের কাজ করা যায়। ফাংশন: গাণিতিক কাজের জন্য স্প্রেডশিট সফটওয়্যারে পূবের্ থেকে সংরক্ষিত ফমুর্লাই হলো ফাংশন। প্রতিটি ফাংশনের একটি সংক্ষিপ্ত রূপ আছে। ফাংশন হচ্ছে ফমুর্লার সংক্ষিপ্ত রূপ যেখানে বিভিন্ন গাণিতিক সূত্র পূবর্ থেকেই সন্নিবেশিত থাকে। অথার্ৎ ফমুর্লাকে সংক্ষিপ্ত আকারে ব্যবহারের পদ্ধতিকে ফাংশন বলে। ফাংশন লেখার নিয়ম: •  প্রথমে সমান চিহ্ন (=) দিয়ে ফাংশন টাইপ শুরম্ন করতে হয়। • ফাংশনের ডানপাশে বন্ধনী থাকে এবং বন্ধনীর মধ্যে আগুের্মন্ট টাইপ করতে হয়। • একাধিক আগুের্মন্ট থাকলে কমাচিহ্ন (,) বা কোলন চিহ্ন (;) দিয়ে পৃথক করে দেখাতে হয়। • ফাংশন এক্সপ্রেশনে সবাির্ধক ২৫৫ বণর্ ব্যবহৃত হতে পারে। • আগুের্মন্ট হিসাবে সংখ্যাও থাকতে পারে। • একটি ফাংশনে সবোর্চ্চ ৩০টি পযর্ন্ত্ম আগুের্মন্ট ব্যবহার করা যায়। • টেক্সট ফাংশনে আগুের্মন্ট কোটেশন চিহ্নের ভেতরে রাখতে হয়। • ফাংশন লেখার সময় বড় বা ছোট হাতের অক্ষর ব্যবহার করা যায়। • ফাংশন ও আগুের্মন্ট এর বর্যাকেটের মাঝে ফাঁকা রাখা যাবে না। • কিছু ফাংশন আছে যেগুলোর আগুের্মন্ট প্রয়োজন হয় না।', null, null, 'short', null, 4, false),
  ('ict-lec-ch04-saq-014', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ফমুর্লা ও ফাংশনের মধ্যে পাথর্ক্য লেখ।', 'short', null, null, 'ফমুর্লা ও ফাংশনের পাথর্ক্য নিচে দেওয়া হলো: ফমুর্র্লা ফাংশন', null, null, 'short', null, 4, false),
  ('ict-lec-ch05-saq-003', 'class9-ict-bn-guide', 'ict-lecture-satt', 'মাল্টিমিডিয়া বলতে কী বোঝ? মাল্টিমিডিয়ার উন্নয়নে ডিজিটাল যন্ত্রের অবদান ব্যাখ্যা কর।', 'short', null, null, 'মাল্টিমিডিয়া হলো মানুষের বিভিন্ন প্রকাশ মাধ্যমের সমন্বয়। আমরা অন্ত্মত তিনটি মাধ্যম বা মিডিয়া ব্যবহার করে নিজেদেরকে প্রকাশ করি। বণর্, চিত্র এবং শব্দ নামের এই মাধ্যমগুলোর বিভিন্ন রূপও রয়েছে। এই তিনটি মাধ্যম তাদের বিভিন্ন রূপ নিয়ে কখনো আলাদাভাবে, কখনো একসাথে আমাদের সামনে আবিভূর্ত হয়। এসব মাধ্যমের প্রকাশকে আমরা কাগজের প্রকাশনা, রেডিও, টেলিভিশন, ভিডিও, সিনেমা, ভিডিও গেমস, শিক্ষামূলক সফটওয়্যার, ওয়েব পেজ ইত্যাদি নানা নামে চিনি। এগুলোর মধ্যে কাগজের প্রকাশনা বা রেডিওকে মাল্টিমিডিয়া বলা যাবে না। তবে টেলিভিশন-ভিডিও-সিনেমাকে আমরা মাল্টিমিডিয়া বলতে পারি। আবার ভিডিও গেমস, শিক্ষামূলক সফটওয়্যার বা ওয়েব পেজকে আমরা ইন্টারঅ্যাকটিভ মাল্টিমিডিয়া বলতে পারি। মাল্টিমিডিয়ার উন্নয়নে ডিজিটাল যন্ত্রের অবদান: বতর্মান সময়ে সবচেয়ে জনপ্রিয় যন্ত্র হচ্ছে কম্পিউটার। এই যন্ত্রটি দিয়ে হিসাব-নিকাশ থেকে শুরম্ন করে তথ্য প্রক্রিয়াকরণ, তথ্য পারাপার, লেখালেখি, গবেষণা, বিনোদন, যোগাযোগ ইত্যাদি অসংখ্য কাজ করা যায়। কিন্তু শুরম্নতে এই যন্ত্রটি দিয়ে কাজ করার জন্য একটি মাত্র মিডিয়া-তথা বণর্ ব্যবহার করতে হতো। কিন্তু কালক্রমে কম্পিউটারে চিত্র এবং শব্দ সমন্বিত হয়। তাছাড়া কম্পিউটারের রয়েছে প্রোগ্রামিং করার ক্ষমতা। বস্তুত কম্পিউটারের মাল্টিমিডিয়া মানে হলো বণর্, চিত্র ও শব্দের সমন্বয়ে একটি ইন্টারঅ্যাকটিভ অভিজ্ঞতা। অতীতের চেয়ে এখনকার মাল্টিমিডিয়ার অভিজ্ঞতা অনেক সমৃদ্ধ। যন্ত্র হিসেবেও মাল্টিমিডিয়ার বাহন হিসেবে এখন কেবল ইলেকট্রনিক বা কম্পিউটারই ব্যবহৃত হয় না পাশাপাশি আমাদের হাতের কাছের মোবাইল ফোন, স্মাটর্ ফোন, ট্যাবলেট ও অন্যান্য ডিজিটাল যন্ত্র এখন মাল্টিমিডিয়া ধারণ ও পরিচালনার জন্য ব্যবহৃত হয়।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-004', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ইন্টারঅ্যাকটিভ মাল্টিমিডিয়া কী? মাল্টিমিডিয়ার প্রয়োগ সম্পকের্ লেখ।', 'short', null, null, 'ইন্টারঅ্যাকটিভ মাল্টিমিডিয়া: ইন্টারঅ্যাকটিভ মাল্টিমিডিয়া হচ্ছে সেইসব বহু মাধ্যম যার সাথে ব্যবহারকারী যোগাযোগ করতে পারে। ভিডিও গেমস, শিক্ষামূলক সফটওয়্যার, ওয়েব পেজ ইত্যাদি ইন্টারঅ্যাকটিভ মাল্টিমিডিয়ার উদাহরণ। •  মাল্টিমিডিয়ার প্রয়োগ: মানুষ মনের ভাব প্রকাশ করার জন্য যেসব মাধ্যম ব্যবহার করে সেগুলোর সমন্বিত রূপই হচ্ছে মাল্টিমিডিয়া। নিচে মাল্টিমিডিয়ার প্রয়োগ বণর্না করা হলো: •  বণর্ বা টেক্সট: সারা দুনিয়াতেই টেক্সটের যাবতীয় কাজ এখন কম্পিউটারে হয়ে থকে। একসময় টাইপরাইটার ও ফটোটাইপসেটার দিয়ে অফিস-আদালতে কাজ করা হতো। বতর্মানে সবর্ত্রই কম্পিউটার পৌঁছেছে। এ অবস্থা বিশ্বের সব দেশেই বিদ্যমান। মুদ্রণ ও প্রকাশনায় কম্পিউটারের ব্যবহার নিরঙ্কুশ। •  চিত্র বা গ্রাফিক্স: দুনিয়ার সবর্ত্রই গ্রাফিক্স তৈরি, সম্পাদনা ইত্যাদি যাবতীয় কাজ কম্পিউটার ব্যবহার করেই করা হয়। আমাদের দেশে গ্রাফিক্স ডিজাইন, পেইন্টিং, ড্রইং বা কমাশির্য়াল গ্রাফিক্স নামক চারম্নকলার যে অংশটি রয়েছে তাতে কম্পিউটারের ব্যবহার অত্যন্ত্ম সীমিত। তবে ব্যতিক্রম হচ্ছে মুদ্রণ ও প্রকাশনা। মুদ্রণ ও প্রকাশনায় গ্রাফিক্স ডিজাইনের ক্ষেত্রে কম্পিউটারের ব্যবহার শুরম্ন হয় নব্বই দশকে। প্রথমে ফটোশপ দিয়ে স্ক্যান করা ছবি সম্পাদনা দিয়ে এর সূচনা হয়। ক্রমশ ডিজাইন এবং গ্রাফিক্সে কম্পিউটার জায়গা করে নিতে থাকে। ইতোমধ্যেই বিজ্ঞাপন, সাইনবোডর্, অ্যানিমেশন, স্থাপত্য ইত্যাদি সকল ক্ষেত্রেই কম্পিউটার ব্যবহৃত হচ্ছে। •  শব্দ বা অডিও: শব্দ বা অডিও রেকডর্, সম্পাদনা ইত্যাদি ক্ষেত্রে সারা দুনিয়া এখন কম্পিউটারের ওপর নিভর্র করে। সাউন্ড ইঞ্জিনিয়ারিংয়ে এনালগ পদ্ধতি এখন কাযর্ত সম্পূণর্ অচল হয়ে পড়েছে। যে কেউ ইচ্ছে করলেই একটি ভালো কম্পিউটার দিয়ে উন্নতমানের সাউন্ড রেকডির্ং করতে পারেন। •  মাল্টিমিডিয়া সফটওয়্যার: বাংলাদেশে মাল্টিমিডিয়া সফটওয়্যার প্রস্তুত হওয়া কেবল শুরম্ন হয়েছে। বাংলাদেশ-৭১, অবসর, বিশ্বকোষ, নামায শিক্ষা, বিজয় শিশু শিক্ষা- এমন কয়েকটি সিডিতে মাল্টিমিডিয়া প্রযুক্তি প্রয়োগ করা হয়েছে। •  ডিজিটাল প্রকাশনা: আমাদের প্রকাশনা জগৎ এখনও কাগজনিভর্র। তবে একুশ শতক অবশ্যই ডিজিটাল প্রকাশনার শতক হবে বাংলাদেশেও। সামগ্রিকভাবে বাংলাদেশ মাল্টিমিডিয়ার প্রয়োগ আশাব্যঞ্জক না হলেও কোনো কোনো ক্ষেত্রে বাংলাদেশ বিশ্বপযাের্য়র। আশার বিষয় হচ্ছে, বাংলাদেশ অতি দ্রম্নত প্রযুক্তি গ্রহণ করে থাকে। মাল্টিমিডিয়ার ক্ষেত্রেও তাই ঘটবে বলে আশা করা যায়।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-005', 'class9-ict-bn-guide', 'ict-lecture-satt', 'কম্পিউটার মাল্টিমিডিয়া কী? মাল্টিমিডিয়ার উন্নয়নে গ্রাফিক্সের ভূমিকা বণর্না কর।', 'short', null, null, 'কম্পিউটার মাল্টিমিডিয়া মানে হলো বণর্, চিত্র ও শব্দের সমন্বয়ে একটি ইন্টারঅ্যাকটিভ অভিজ্ঞতা। মাল্টিমিডিয়ার উন্নয়নে গ্রাফিক্সের ভূমিকা নিচে আলোচনা করা হলো: •  ভিডিও-টিভি: ভিডিও কাযর্ত এক ধরনের গ্রাফিক্স। একে চলমান গ্রাফিক্স বললে ভালো হয়। বিশ্বজুড়ে ভিডিও একটি সুপ্রতিষ্ঠিত মিডিয়া। টিভি, হোম ভিডিও, মাল্টিমিডিয়া সফটওয়্যার, ওয়েব ইত্যাদি সকল ক্ষেত্রেই ভিডিওর ব্যবহার ব্যাপক। বিশ্বজুড়ে ভিডিও এখন এনালগ থেকে ডিজিটালে রূপান্ত্মরিত হচ্ছে। এখন কাযর্ত এনালগ পযাের্য় ভিডিও ধারণ, সম্পাদনা ও সংরক্ষণ করার কোনো উপায়ই নেই। এমনকি ভিডিও সম্প্রচারও এনালগ থেকে ডিজিটাল হয়ে যাচ্ছে। •  অ্যানিমেশন: অ্যানিমেশনও এক ধরনের গ্রাফিক্স বা চিত্র। তবে সেটি চলমান বা স্থির হতে পারে। এটি দ্বিমাত্রিক বা ত্রিমাত্রিক হতে পারে। আমাদের দেশে অ্যানিমেশনের ব্যবহার ক্রমশ ব্যাপক হচ্ছে। বিশেষত বিজ্ঞাপন চিত্রে অ্যানিমেশন একটি প্রিয় বিষয়। তবে অ্যানিমেশনে কাজ করার লোকের অভাব রয়েছে। আসলে অ্যানিমেশন কখনই কেবলমাত্র একক মিডিয়া হিসেবে ব্যবহৃত হয় না। এর সাথে অডিও, ভিডিও, টেক্সট, গ্রাফিক্স ইত্যাদির সম্পকর্ রয়েছে। •  সিনেমা: সিনেমা গ্রাফিক্সের আরও একটি রূপ। সিনেমায় গ্রাফিক্সের ব্যবহার ব্যাপক। তবে ভিডিও এবং সিনেমার মাঝে প্রযুক্তিগত পাথর্ক্য দিন দিন কমে আসছে।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-006', 'class9-ict-bn-guide', 'ict-lecture-satt', 'মাইক্রোসফট পাওয়ারপয়েন্ট কী? কম্পিউটারে পাওয়ারপয়েন্ট প্রোগ্রাম খোলার কৌশল আলোচনা কর।', 'short', null, null, 'মাইক্রোসফট পাওয়ারপয়েন্ট হচ্ছে মাইক্রোসফট অফিসের অন্ত্মভুর্ক্ত একটি সফটওয়্যার। এ সফটওয়্যারের সাহায্যে লেখা, ছবি, অডিও, ভিডিও, গ্রাফ ইত্যাদির সমন্বয়ে আকষর্ণীয় এবং কাযর্করভাবে তথ্যাদি উপস্থাপন করা যায়। কম্পিউটারে পাওয়ার পয়েন্ট প্রোগ্রাম খোলার কৌশল নিচে আলোচনা করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-008', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশনে স্স্নাইড প্রদশের্নর কৌশল বণর্না কর।', 'short', null, null, 'সভা, সেমিনার-সিম্পোজিয়াম, কমর্শালা ইত্যাদিতে কম্পিউটারের সাহায্যে আকষর্ণীয় এবং কাযর্করভাবে তথ্য উপস্থাপন করার পদ্ধতিতে প্রেজেন্টেশন বলে। নিচে প্রেজেন্টেশনে স্স্নাইড প্রদশের্নর কৌশল বণর্না করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-009', 'class9-ict-bn-guide', 'ict-lecture-satt', 'স্স্নাইড তৈরির পর স্স্নাইডে ব্যাকগ্রাউন্ড যুক্ত বা ব্যাকগ্রাউন্ড পরিবতর্ন করার উপায় বণর্না কর।', 'short', null, null, 'প্রেজেন্টেশনের এক একটি অংশকে স্স্নাইড বলা হয়। কোনো স্স্নাইড তৈরি করার সময় এবং স্স্নাইড তৈরির পরও ব্যাকগ্রাউন্ডের রং পরিবতর্ন করা যায় বা নতুন করে ব্যাকগ্রাউন্ড যুক্ত করা যায়। নিচে স্স্নাইডে ব্যাকগ্রাউন্ড যুক্ত বা পরিবতর্ন করার উপায় বণর্না করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-010', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশন ও স্স্নাইড কী? স্স্নাইডে ছবি যোগ করার কৌশল বণর্না কর।', 'short', null, null, 'একটি পাওয়ার পয়েন্ট ফাইলকে প্রেজেন্টেশন বলা হয়। আর পাওয়ার পয়েন্ট প্রেজেন্টেশনের এক একটি পৃষ্ঠাকে স্স্নাইড বলা হয়। মাইক্রোসফট ওয়াডের্ যেমন অনেকগুলো পৃষ্ঠা থাকতে পারে, তেমনি একটি প্রেজেন্টেশনের একাধিক স্স্নাইড থাকে। একাধিক স্স্নাইডবিশিষ্ট স্স্নাইডে ছবি যোগ করার কৌশল:পাওয়ার পয়েন্ট স্স্নাইডে মাইক্রোসফট ক্লিপআটর্ বা অন্য কোনো উৎস হতে প্রয়োজনীয় ছবি সংযোজন করা যায়। ছবি সংযোজনের পদ্ধতি নিচে আলোচনা করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-011', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশন স্স্নাইডে ভিডিও সংযোগ করার নিয়ম লেখ।', 'short', null, null, 'প্রেজেন্টেশন স্স্নাইডে ভিডিও যুক্ত করা যায়। প্রয়োজন অনুযায়ী যেকোনো স্স্নাইডে ভিডিও যুক্ত করা যেতে পারে। তবে সাধারণত শুরম্নর স্স্নাইডে ভিডিও যুক্ত করা হয়। নিচে স্স্নাইডে ভিডিও যুক্ত করার নিয়ম বণর্না করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-012', 'class9-ict-bn-guide', 'ict-lecture-satt', 'পাওয়ার পয়েন্টকে প্রেজেন্টেশন প্রোগ্রাম বলা হয় কেন?', 'short', null, null, 'যে সকল কারণে পাওয়ার পয়েন্টকে প্রেজেন্টেশন প্রোগ্রাম বলা হয় তার কারণ নিচে তুলে ধরা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-013', 'class9-ict-bn-guide', 'ict-lecture-satt', 'স্স্নাইডের টেক্সট বক্সের লেখায় ট্রানজিশন প্রয়োগ করার কৌশল বণর্না কর।', 'short', null, null, 'একটি স্স্নাইডে একাধিক টেক্সট বক্সে লেখা থাকতে পারে। এসব টেক্সট বক্সে ভিন্ন ভিন্ন ট্রানজিশন প্রয়োগ করলে টেক্সট বক্সগুলো ভিন্ন ভিন্ন প্রক্রিয়ায় স্স্নাইডের ভেতরে আসবে। নিচে টেক্সট বক্সে ট্রানজিশন প্রয়োগ করার কৌশল বণর্না করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-014', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশন সফটওয়্যাররের গুরম্নত্ব লেখ।', 'short', null, null, 'মাইক্রোসফট কপোের্রশনের তৈরি পাওয়ার পয়েন্ট সফটওয়্যারটি ব্যবহার করে সুন্দর সস্নাইড তৈরি করা ছাড়াও আরও অনেক কাজ অতি সহজে করা যায়। নিচে প্রেজেন্টেশন সফটওয়্যারের গুরম্নত্ব তুলে ধরা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-017', 'class9-ict-bn-guide', 'ict-lecture-satt', 'কম্পিউটারে ফটোশপ প্রোগ্রাম খোলার কৌশল বণর্না কর।', 'short', null, null, 'কম্পিউটারে ছবি সম্পাদনার জন্য সবচেয়ে জনপ্রিয় প্রোগ্রাম হলো এডোবি ফটোশপ প্রোগ্রাম। ফটোশপে কাজ করার জন্য আমাদের কম্পিউটারে ফটোশপ প্রোগ্রাম ইনস্টল করা থাকতে হবে অথবা তা ইনস্টল করে নিতে হবে। নিচে ফটোশপ প্রোগ্রাম খেলার কৌশল বণর্না করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-019', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ফটোশপের সিলেকশন টুল এবং মুভ টুলের পরিচিতি লেখ।', 'short', null, null, 'ফটোশপের সিলেকশন টুল এবং মুভ টুলের পরিচিতি নিচে বণর্না করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-021', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ফটোশপে ফেদার ও ইরেজার টুলের ব্যবহার লেখ।', 'short', null, null, 'ফটোশপে ফেদার-এর ব্যবহার:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-024', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ক্রপ টুলের সাহায্যে ছবির অপ্রয়োজনীয় অংশ বাদ দেওয়ার পদ্ধতি আলোচনা কর।', 'short', null, null, 'ক্রপ টুলের সাহায্যে ছবির অপ্রয়োজনীয় অংশ বাদ দেওয়ার পদ্ধতি নিচে আলোচনা করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-025', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ফটোশপে ক্রপ টুল ব্যবহারের প্রক্রিয়া লেখ।', 'short', null, null, 'ফটোশপে কোনো ছবি ক্রপ করতে হলে নিচের ধাপগুলো সম্পন্ন করতে হবে:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-027', 'class9-ict-bn-guide', 'ict-lecture-satt', 'এডোবি ইলাস্ট্রেটর কী? ইলাস্ট্রেটর প্রোগ্রাম খোলার প্রক্রিয়া লেখ।', 'short', null, null, 'এডোবি ইলাস্ট্রেটর: এডোবি ইলাস্ট্রেটর হচ্ছে মূলত ছবি আঁকা, নকশা প্রণয়ন করা, লোগো তৈরি করা এবং অন্যান্য ডিজাইন তৈরি করার প্রোগ্রাম। এডোবি ফটোশপ প্রোগ্রামের সাহায্যে যেমন ডিজাইনের কাজ করার সুযোগ খুবই সীমিত, তেমনি এডোবি ইলাস্ট্রেটরে ছবি সম্পাদনার সুযোগ প্রায় নেই বললেই চলে। ইলাস্ট্রেটরের প্রধান কাজই হচ্ছে অঙ্কন শিল্পের কাজ। ইলাস্ট্রেটর প্রোগ্রাম খোলার প্রক্রিয়া: অন্য যেকোনো প্রোগ্রামের মতোই ইলাস্ট্রেটরে কাজ করার জন্য ইলাস্ট্রেটর প্রোগ্রামটি খুলে নিতে হয়। ইলাস্ট্রেটর প্রোগ্রাম খোলার প্রক্রিয়া নিচে বণর্না করা হলো:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-028', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ইলাস্ট্রেটরে অবজেক্ট তৈরি করার কৌশল বণর্না কর।', 'short', null, null, 'ফটোশপে অবজেক্ট তৈরির প্রস্তুতি পযাের্য় বিভিন্ন ধরনের আকৃতি তৈরির প্রাথমিক কাজ করার প্রক্রিয়া ও পদ্ধতি আয়ত্ত করে নেওয়া প্রয়োজন। যেমন- বগার্কার ও আয়তাকার আকৃতি তৈরি করা, বৃত্তাকার ও ডিম্বাকার আকৃতি তৈরি করা, বহুকোণবিশিষ্ট আকৃতি, তারকার আকৃতি, পেঁচানো আকৃতি ইত্যাদি তৈরি করা। একটি অবজেক্ট তৈরির জন্য:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-032', 'class9-ict-bn-guide', 'ict-lecture-satt', 'ইলাস্ট্রেটরে ছবি যোগ করার প্রক্রিয়া লেখ।', 'short', null, null, 'ইলাস্ট্রেটরে ছবি বা ইমেজ স্থাপন করার জন্য নিচের ধাপগুলো সম্পন্ন করতে হবে:', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-069', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশন কী? প্রেজেন্টেশনে নতুন স্াইড যোগ করার কৌশল বণর্না কর।', 'short', null, null, 'প্রেজেন্টেশন : কোনো সভা, সেমিনার-সিম্পোজিয়াম, কমর্শালা ও ক্লাসরুম ইত্যাদিতে কম্পিউটারের সাহায্যে আকষর্ণীয় এবং কাযর্করভাবে তথ্য উপস্থাপনের প্রক্রিয়াকে প্রেজেন্টেশন বলা হয়। প্রেজেন্টেশনের এক একটি অংশকে স্াইড বলা হয়। প্রেজেন্টেশনে নতুন স্াইড যোগ করার কৌশল : প্রেজেন্টেশনে নতুন স্াইড যোগ করার কৌশল নিচে বণর্না করা হলো : ১. ঐড়সব মেনুর রিবন থেকে ঘবি ঝষরফব কমান্ড সিলেক্ট করলে বা কীবোডের্র ঈঃৎষ বোতাম চেপে রেখে গ বোতামে চাপ দিলে একটি নতুন স্াইড যুক্ত হবে। ২. নতুন যুক্ত হওয়া স্াইডে ঈষরপশ:ড় ধফফ:রঃষব এবং ঈষরপশ:ড় ধফফ:বীঃ লেখা থাকবে। লেখা দুটির উপর ক্লিক করলে টেক্সট বক্স দৃশ্যমান হবে এবং টেক্সট বক্সের মধ্যে ইনসাসর্ন পয়েন্টার থাকবে। ইনসাসর্ন পয়েন্টার থাকা অবস্থায় শিরোনাম এবং উপ-শিরোনাম টাইপ করা যাবে। বাম পাশের থাম্বনেইল উইন্ডোতে নতুন যুক্ত হওয়া স্াইডের ছোট সংস্করণ দেখা যাবে। ৩. এভাবে নতুন স্াইড যুক্ত করে প্রয়োজন অনুযায়ী প্রেজেন্টেশন তৈরির কাজ সম্পন্ন করতে হবে।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-070', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশনে স্াইড প্রদশের্নর কৌশল বণর্না কর।', 'short', null, null, 'সভা, সেমিনার-সিম্পোজিয়াম, কমর্শালা ইত্যাদিতে কম্পিউটারের সাহায্যে আকষর্ণীয় এবং কাযর্করভাবে তথ্য উপস্থাপন করার পদ্ধতিতে প্রেজেন্টেশন বলে। নিচে প্রেজেন্টেশনে স্াইড প্রদশের্নর কৌশল বণর্না করা হলো : ১. কীবোডের্র ঋ৫ বোতামে চাপ দিলে অথবা ঠরবি মেনুর রিবন থেকে ঝষরফব ঝযড়ি সিলেক্ট করলে অথবা স্ট্যাটাস বার-এ ঝষরফব ঝযড়ি আইকন ক্লিক করলে প্রেজেন্টেশনের প্রথম স্াইডটি উপস্থাপিত হবে। ২. প্রেজেন্টেশনের একটি স্াইড থেকে পরবতীর্ স্াইডে যাওয়ার জন্য কীবোডের্র ডানমুখী তীর বোতামে চাপ দিতে হবে। পূবর্বতীর্ স্াইডে ফেরার জন্য বামমুখী তীর বোতামে চাপ দিতে হবে। ৩. প্রেজেন্টেশনের মাঝামাঝি কোনো অবস্থানে থাকা অবস্থায় ওই স্াইড থেকে পরবতীর্ প্রদশর্ন শুরু করার জন্য কীবোডের্র শিফট বোতাম চেপে রেখে ঋ৫ বোতামে চাপ দিতে হবে। ৪. স্াইড শো উইন্ডো থেকে সম্পাদনার উইন্ডোতে ফিরে যাওয়ার জন্য কীবোডের্র ঊংপ বোতামে চাপ দিতে হবে।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-071', 'class9-ict-bn-guide', 'ict-lecture-satt', 'স্াইড তৈরির পর স্াইডে ব্যাকগ্রাউন্ড যুক্ত বা ব্যাকগ্রাউন্ড পরিবতর্ন করার উপায় বণর্না কর।', 'short', null, null, 'প্রেজেন্টেশনের এক একটি অংশকে স্াইড বলা হয়। কোনো স্াইড তৈরি করার সময় এবং স্াইড তৈরির পরও ব্যাকগ্রাউন্ডের রং পরিবতর্ন করা যায় বা নতুন করে ব্যাকগ্রাউন্ড যুক্ত করা যায়। নিচে স্াইডে ব্যাকগ্রাউন্ড যুক্ত বা পরিবতর্ন করার উপায় বণর্না করা হলো : ১. যে স্াইডে ব্যাকগ্রাউন্ড ব্যবহার করতে হবে সেই স্াইডটি খোলা রাখতে হবে বা সক্রিয় রাখতে হবে। ২. এরপর উবংরমহ মেনুর রিবনে একেবারে ডান দিকে ইধপশমৎড়ঁহফ ঝঃুষব ড্রপ-ডাউন বার-এ ক্লিক করলে গ্রেডিয়েন্ট এবং সলিড রঙের একটি প্যালেট আসবে। এ প্যালেটের যে রং বা গ্রেডিয়েন্টের সসের উপর মাউস পয়েন্টার স্থাপন করা হবে মূল স্াইডে সেই রং বা গ্রেডিয়েন্টের ব্যাকগ্রাউন্ড দেখা যাবে। পছন্দ হলে ওই সসে ক্লিক করতে হবে। ব্যাকগ্রাউন্ড হিসেবে আরও রং, টেক্সার এবং ছবি ব্যবহার করার ক্ষেত্রে। ৩. প্যালেটের নিচের দিকে ঋড়ৎসধঃ ইধপশমৎড়ঁহফ সিলেক্ট করতে হবে। এতে ঋড়ৎসধঃ ইধপশমৎড়ঁহফ ডায়ালগ বক্স আসবে। ৪. ঋড়ৎসধঃ ইধপশমৎড়ঁহফ ডায়ালগ বক্সের উপরের বাম পাশে ঝড়ষরফ ভরষষ রেডিও বোতামে ক্লিক করে সক্রিয় করে দিতে হবে। এরপর ঈড়ষড়ৎ ড্রপ-ডাউন তীরে ক্লিক করলে রঙের প্যালেট আসবে। এর রঙের প্যালেট থেকে যে রঙের সসের উপর ক্লিক করা হবে স্াইডের ব্যাকগ্রাউন্ড হিসেবে সেই রং আরোপিত হবে। ৫. চরপঃঁৎব ড়ৎ ঞবীঃঁৎব ভরষষ রেডিও বোতামে ক্লিক করে সক্রিয় করে দিলে ঈড়ষড়ৎ-এর জায়গা ঞবীঁৎব Wªc- ডাউন আসবে। এ ড্রপডাউন তীরে ক্লিক করলে বিভিন্ন প্রকার টেক্সার প্রদশির্ত হবে। এর ভেতর থেকে যে টেক্সারের সসে ক্লিক করা হবে, মূল স্াইডে সেই টেক্সার আরোপিত হবে। ৬. ডায়ালগ বক্সের ওহংবৎঃ বোতামে ক্লিক করলে ডায়ালগ বক্স চলে যাবে এবং ওই ছবি স্াইডের ব্যাকগ্রাউন্ড হিসেবে আরোপিত হবে।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-072', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশন ও স্াইড কী? স্াইডে ছবি যোগ করার কৌশল বণর্না কর।', 'short', null, null, 'প্রেজেন্টেশন ও স্াইড : একটি পাওয়ার পয়েন্ট ফাইলকে প্রেজেন্টেশন বলা হয়। আর পাওয়ার পয়েন্ট প্রেজেন্টেশনের এক একটি পৃষ্ঠাকে স্াইড বলা হয়। মাইক্রোসফট ওয়াডের্ যেমন অনেকগুলো পৃষ্ঠা থাকতে পারে, তেমনি একটি প্রেজেন্টেশনের একাধিক স্াইড থাকে। একাধিক স্াইডবিশিষ্ট স্স্নাইডে ছবি যোগ করার কৌশল : পাওয়ার পয়েন্ট স্াইডে মাইক্রোসফট ক্লিপআটর্ বা অন্য কোনো উৎস হতে প্রয়োজনীয় ছবি সংযোজন করা যায়। ছবি সংযোজনের পদ্ধতি নিচে আলোচনা করা হলো : ১. ওহংবৎঃ রিবনে গিয়ে ঢ়রপঃঁৎব আইকনে ক্লিক করতে হবে। ২. চরপঃঁৎব খরনৎধৎু গ্যালারিতে অবস্থিত ছবি তালিকা প্রদশির্ত হবে। যদি চরপঃঁৎব খরনৎধৎু থেকে ছবি না নিয়ে অন্য কোনো লোকেশন থেকে ছবি নেয়ার প্রয়োজন হয় তবে সেই লোকেশনে যেতে হবে। তা থেকে পছন্দের ছবি নিবার্চন করে তাতে ডাবল ক্লিক বা ওহংবৎঃ বাটনে ক্লিক করতে হবে। ৩. ফলে ছবিটি স্াইডে প্রদশির্ত হবে। এভাবে পাওয়ার পয়েন্ট স্াইডে ছবি যুক্ত করা যাবে।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-073', 'class9-ict-bn-guide', 'ict-lecture-satt', 'প্রেজেন্টেশন স্াইডে ভিডিও সংযোগ করার নিয়ম লেখ।', 'short', null, null, 'প্রেজেন্টেশন স্াইডে ভিডিও যুক্ত করা যায়। প্রয়োজন অনুযায়ী যেকোনো স্াইডে ভিডিও যুক্ত করা যেতে পারে। তবে সাধারণত শুরুর স্াইডে ভিডিও যুক্ত করা হয়। নিচে স্াইডে ভিডিও যুক্ত করার নিয়ম বণর্না করা হলো : ১. যে স্াইডে ভিডিও সংযোগ করতে হবে সেই স্াইডটি ঙঢ়বহ করতে হবে। ২. ওহংবৎঃ রিবনে ক্লিক করার পর গড়ারব আইকন ক্লিক করে গড়ারব ঋৎড়স ঋরষব অপশনটি সিলেক্ট করতে হবে। ৩. ডায়ালগ বক্স থেকে প্রয়োজনীয় মুভিটি সিলেক্ট করে এর ঙশ বাটনে ক্লিক করতে হবে। ৪. মুভিটি ওপেন হবার আগে একটি ডায়লগ বক্স প্রদশির্ত হবে, যেখানে জানতে চাওয়া হবে মুভিটি অটোমেটিক্যালি চলবে নাকি ক্লিক করলে চলবে। এখান থেকে প্রয়োজন অনুসারে অপশন সিলেক্ট করতে হবে। ৫. ফলে ভিডিওটি স্াইডে যুক্ত হবে। ৬. ভিডিওটি চালানোর জন্য স্াইডশো রিবনে গিয়ে স্াইডটি সিলেক্ট করে ঋৎড়স ঈঁৎৎবহঃ ঝষরফব সিলেক্ট করতে হবে। এখন যেভাবে অপশন সিলেক্ট করা হয়েছে অথার্ৎ হয় অটোমেটিক্যালি নতুবা ক্লিক করলে ভিডিওটি রান করবে। এভাবে পাওয়ার পয়েন্টের স্াইডে ভিডিও যুক্ত করা যাবে।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-075', 'class9-ict-bn-guide', 'ict-lecture-satt', 'স্াইডের টেক্সট বক্সের লেখায় ট্রানজিশন প্রয়োগ করার কৌশল বণর্না কর।', 'short', null, null, 'একটি স্াইডে একাধিক টেক্সট বক্সে লেখা থাকতে পারে। এসব টেক্সট বক্সে ভিন্ন ভিন্ন ট্রানজিশন প্রয়োগ করলে টেক্সট বক্সগুলো ভিন্ন ভিন্ন প্রক্রিয়ায় স্াইডের ভেতরে আসবে। নিচে টেক্সট বক্সে ট্রানজিশন প্রয়োগ করার কৌশল বণর্না করা হলো : ১. স্াইডটি খোলা রাখতে হবে। ২. প্রথম টেক্সট বক্সটি সিলেক্ট করতে হবে। ৩. ধহরসধঃরড়হং মেনুতে ক্লিক করে সক্রিয় করতে হবে। ধহরসধঃরড়হং এর নিচে ঈঁংঃড়স অহরসধঃরড়হ-এর একটি প্যালেট আসবে। ৪. ঈঁংঃড়স অহরসধঃরড়হ প্যালেটের অফফ ঊভভবপঃ ড্রপডাউন তালিকা থেকে ঊহঃৎধহপব সিলেক্ট করলে কাস্টম ট্রানজিশনের একটি তালিকা আসবে। এ তালিকা থেকে- প্রথম টেক্সট বক্সের জন্য ইষরহফং সিলেক্ট করা হলো। দ্বিতীয় টেক্সট বক্সটি সিলেক্ট করে ঋষু রহ সিলেক্ট করা হলো। তৃতীয় টেক্সট বক্সটি সিলেক্ট করে উরধসড়হফ সিলেক্ট করা হলো। এ তালিকা থেকে গড়ৎব ঊভভবপঃং সিলেক্ট করলে ট্রানজিশনের আরও একটি তালিকা পাওয়া যাবে। এ তালিকা থেকে যেকোনো ট্রানজিশন সিলেক্ট করলে একই রকম কাজ হবে। ৫. আরোপিত কোনো ট্রানজিশন বাদ দেওয়ার জন্য নিদির্ষ্ট টেক্সট বক্সটি সিলেক্ট করে জবসড়াব বোতামে ক্লিক করতে হবে।', null, null, 'short', null, 5, false),
  ('ict-lec-ch05-saq-096', 'class9-ict-bn-guide', 'ict-lecture-satt', '''বতর্মানে প্রকাশনা শিল্প সম্পূণর্ভাবে গ্রাফিক্স সফটওয়্যার ব্যবহারের উপর নিভর্রশীল''- উক্তিটির যৌক্তিকতা ব্যাখ্যা কর।', 'short', null, null, 'আমাদের দেশের বতর্মান প্রকাশনা শিল্প সম্পূণর্ভাবে গ্রাফিক্স সফটওয়্যার ব্যবহারের ওপর নিভর্রশীল। আর এক্ষেত্রে বহুল ব্যবহৃত সফটওয়্যারটি হচ্ছে এডোবি ইলাস্ট্রেটর। এডোবি ইলাস্ট্রেটর হচ্ছে মূলত ছবি আঁকা, নকশা প্রণয়ন করা, লোগো তৈরি করা এবং অন্যান্য ডিজাইন তৈরি করার প্রোগ্রাম। এডোবি ফটোশপ প্রোগ্রামের সাহায্যে যেমন ডিজাইনের কাজ করার সুযোগ খুবই সীমিত, তেমনি এডোবি ইলাস্ট্রেটরে ছবি সম্পাদনার সুযোগ প্রায় নেই বললেই চলে। ইলাস্ট্রেটরের প্রধান কাজই হচ্ছে অঙ্কন শিল্পের কাজ। আমাদের দেশে গল্প, কবিতা, উপন্যাস, প্রবন্ধ ইত্যাদি প্রকাশনার প্রচ্ছদ তৈরি করার জন্য শিল্পীরা এখন রং তুলির ব্যবহার ছেড়ে দিয়েছেন বললেই চলে। এডোবি ইলাস্ট্রেটর ব্যবহার করেই এখন তাঁরা প্রচ্ছদ তৈরির কাজ করে থাকেন। আমন্ত্রণপত্র, বিজ্ঞাপন ইত্যাদি ছোট-বড় কাজসহ বিভিন্ন আকারের পোস্টার, বিশাল আকারের ব্যানার, বিলবোডর্ ইত্যাদি তৈরির কাজ এখন ইলাস্ট্রেটর ছাড়া ভাবাই যায় না। কম্পিউটার ব্যবহার করে ডিজাইনের কাজ করার জন্য আরও অনেক প্রোগ্রাম রয়েছে। কিন্তু, কাজের সুবিধা এবং বৈচিতের্যর জন্য ইলাস্ট্রেটরের চাহিদা বেশি। এসব কারণে, ইলাস্ট্রেটর প্রোগ্রামটি বতর্মানে বিশ্বব্যাপী জনপ্রিয়। ইলাস্ট্রেটর প্রোগ্রামে ইংরেজি ও বাংলা লেখালেখির জন্য কম্পিউটারের কীবোডর্ ব্যবহার করা ছাড়া শিল্পীর তুলি দিয়ে লেখার মতো করেও লেখালেখির কাজ করা যায়। লেখার পরে অক্ষর বা অক্ষরসমূহের আকার এবং আকৃতি যেভাবে ইচ্ছা বা প্রয়োজন সেভাবেই পরিবতর্ন করে নেওয়া যায়। এসব নানা রকম সুবিধার কারণে ''বতর্মানে প্রকাশনা শিল্প সম্পূণর্ভাবে গ্রাফিক্স সফটওয়্যার ব্যবহারের ওপর নিভর্রশীল''।', null, null, 'short', null, 5, false),
  ('ict-lec-ch06-saq-001', 'class9-ict-bn-guide', 'ict-lecture-satt', 'মেশিন কোড কী? প্রোগ্রাম কোডকে মেশিন কোডে রূপান্ত্মরের উপায় লিখ।', 'short', null, null, 'মেশিন কোড হলো কম্পিউটারের সরাসরি বোঝার উপযোগী বাইনারি (০ ও ১) ভাষায় লিখিত নিদের্শসমূহ। এটি লো- লেভেল ভাষা, যা প্রসেসর সরাসরি কাযর্কর করতে পারে। উচ্চ স্ত্মরের প্রোগ্রামিং ভাষার কোড অনুবাদক সফটওয়্যার (কম্পাইলার বা ইন্টারপ্রেটার) দ্বারা মেশিন কোডে রূপান্ত্মরিত হয়। প্রোগ্রাম কোডকে মেশিন কোডে রূপান্ত্মরের উপায়', null, null, 'short', null, 6, false),
  ('ict-lec-ch06-saq-002', 'class9-ict-bn-guide', 'ict-lecture-satt', 'কাস্টিং কনস্ট্রাক্টর ফাংশন বলতে কী বুঝায়? কয়েকটি ফাংশনের নাম লিখ।', 'short', null, null, 'কাস্টিং কনস্ট্রাক্টর ফাংশন হলো ডাটা টাইপ পরিবতের্নর জন্য ব্যবহৃত বিশেষ ফাংশন, যা একটি ডাটা টাইপের মানকে অন্য ডাটা টাইপে রূপান্ত্মর করে। পাইথনের মতো অনেক প্রোগ্রামিং ভাষায়, সংখ্যা, স্ট্রিং বা অন্য ডাটা টাইপকে প্রয়োজন অনুযায়ী পরিবতর্ন করার জন্য এই ফাংশনগুলো ব্যবহৃত হয়। কয়েকটি কাস্টিং কনস্ট্রাক্টর ফাংশনের নাম:', null, null, 'short', null, 6, false),
  ('ict-lec-mt-ch1-model-saq-011', 'class9-ict-bn-guide', 'ict-lecture-satt', 'সনাতন পদ্ধতিতে পাঠদান এবং ই-', 'short', null, null, 'কুড়িগ্রামের রৌমারি উপজেলার যাদুর চর গ্রামের মিলন এখন নিজ গ্রামেই বসে উচ্চশিক্ষা গ্রহণ করতে পারবে, যা সম্ভব হবে ই-লানির্ং পদ্ধতির মাধ্যমে। ই-লানির্ং হলো ইলেকট্রনিক লানির্ং এর সংক্ষিপ্ত রূপ, যা ডিজিটাল প্রযুক্তির সাহায্যে শিক্ষালাভের একটি আধুনিক পদ্ধতি। বতর্মানে বিভিন্ন বিশ্ববিদ্যালয় ও শিক্ষাপ্রতিষ্ঠান তাদের কোসর্ অনলাইনে উন্মুক্ত করে দিয়েছে, ফলে শিক্ষাথীর্রা যে কোনো স্থান থেকে এই কোসর্ করতে পারে। মিলনও চাইলে এসব কোসের্ ভতির্ হয়ে ভিডিও লেকচার দেখতে, লাইভ ক্লাসে অংশ নিতে, হোমওয়াকর্ জমা দিতে এবং অনলাইন পরীক্ষায় অংশগ্রহণ করে ক্রেডিট অজর্ন করতে পারবে। তবে ই-লানির্ং ব্যবহারের জন্য মিলনের কাছে কম্পিউটার, উচ্চগতির ইন্টারনেট সংযোগ, আইএসপি ও প্রয়োজনীয় সফটওয়্যার থাকতে হবে। এই প্রযুক্তি ব্যবহার করে মিলন ঘরে বসেই উচ্চশিক্ষা চালিয়ে যেতে পারবে এবং নিজের স্বপ্ন পূরণের পথে এগিয়ে যেতে সক্ষম হবে। তথ্যপ্রযুক্তির উন্নতির ফলে গ্রামাঞ্চলেও উচ্চশিক্ষা এখন সহজলভ্য হয়ে উঠেছে।', null, null, 'short', null, 1, false),
